-- Read-only production verification after OCCCI migration 014.
select '01 Migration 014 recorded' as check_name, exists(select 1 from public.occci_schema_versions where version='014_member_dashboard_cashier') as passed
union all select '02 Share capital nullable and constrained', exists(select 1 from pg_attribute where attrelid='public.occci_financials'::regclass and attname='share_capital' and not attnotnull) and exists(select 1 from pg_constraint where conrelid='public.occci_financials'::regclass and conname='occci_share_capital_valid' and convalidated)
union all select '03 Receipt RLS and scoped read policy', (select relrowsecurity from pg_class where oid='public.occci_cashier_payments'::regclass) and (select count(*)=1 from pg_policy where polrelid='public.occci_cashier_payments'::regclass) and exists(select 1 from pg_policy where polrelid='public.occci_cashier_payments'::regclass and polname='occci_cashier_read' and polcmd='r' and 'authenticated'::regrole::oid=any(polroles) and position('occci_can_read_branch' in pg_get_expr(polqual,polrelid))>0 and position('occci_can_read_profile' in pg_get_expr(polqual,polrelid))>0 and position('auth.uid()' in pg_get_expr(polqual,polrelid))>0)
union all select '04 Ledger is client read-only', has_table_privilege('authenticated','public.occci_cashier_payments','SELECT') and not has_table_privilege('authenticated','public.occci_cashier_payments','INSERT') and not has_table_privilege('authenticated','public.occci_cashier_payments','UPDATE') and not has_table_privilege('authenticated','public.occci_cashier_payments','DELETE') and not has_table_privilege('anon','public.occci_cashier_payments','SELECT')
union all select '05 Cashier procedure matches tested source', (select md5(prosrc)='9d70b6688764ff8bd2322d4345f312e5' and prosecdef and 'search_path=""'=any(proconfig) from pg_proc where oid='public.occci_record_cashier_payment(uuid,jsonb,integer,uuid,text)'::regprocedure)
union all select '06 Submit and review match tested source', (select md5(prosrc)='8192b8bc53b826ceaf90f3e40375ab61' from pg_proc where oid='public.occci_submit_change(uuid,text,jsonb,text,text)'::regprocedure) and (select md5(prosrc)='bbbe10e14e1625a1f505db9dd83d4f13' from pg_proc where oid='public.occci_review_change(uuid,text,text)'::regprocedure)
union all select '07 Validators match and remain private', (select md5(prosrc)='f9fa466e405eebb28c1bc0b7af5d2367' from pg_proc where oid='public.occci_cashier_amount(jsonb,text)'::regprocedure) and (select md5(prosrc)='2c1568dcc647695853608ea35ff73e34' from pg_proc where oid='public.occci_validate_financial_additions(jsonb)'::regprocedure) and not has_function_privilege('authenticated','public.occci_cashier_amount(jsonb,text)','EXECUTE') and not has_function_privilege('authenticated','public.occci_validate_financial_additions(jsonb)','EXECUTE') and not has_function_privilege('anon','public.occci_cashier_amount(jsonb,text)','EXECUTE') and not has_function_privilege('anon','public.occci_validate_financial_additions(jsonb)','EXECUTE')
union all select '08 Cashier RPC requires authentication', has_function_privilege('authenticated','public.occci_record_cashier_payment(uuid,jsonb,integer,uuid,text)','EXECUTE') and not has_function_privilege('anon','public.occci_record_cashier_payment(uuid,jsonb,integer,uuid,text)','EXECUTE')
union all select '09 Receipt uniqueness index valid', exists(select 1 from pg_index where indexrelid='public.occci_cashier_receipt_unique'::regclass and indisunique and indisvalid and position('branch_id, lower(receipt_number)' in pg_get_indexdef(indexrelid))>0)
union all select '10 Branch and profile scopes unchanged', (select md5(prosrc)='c34360b2bb33bb623fcb70943a000c3c' from pg_proc where oid='public.occci_can_read_branch(text)'::regprocedure) and (select md5(prosrc)='29d23f0e2c8fb22d8ee3cf1d1a636979' from pg_proc where oid='public.occci_can_read_profile(uuid,text)'::regprocedure)
union all select '11 Password guard and manager limits intact', (select md5(prosrc)='6aaebe701570746d26542919a91d2f8d' from pg_proc where oid='public.occci_consume_position_confirmation(text,uuid,jsonb)'::regprocedure) and (select md5(prosrc)='7f552fe759e6919e7074df8115de36ae' from pg_proc where oid='public.occci_require_manager_slot(uuid,jsonb)'::regprocedure) and (select count(*)=2 from pg_index where indexrelid in ('public.occci_one_dm_per_district'::regclass,'public.occci_one_bm_per_branch'::regclass) and indisunique and indisvalid)
union all select '12 No payment receipts created by upgrade', (select count(*)=0 from public.occci_cashier_payments)
order by check_name;
